replacements.old:
  run: ${{ matrix.command }}
- name: Validate safe failure diagnostics
  id: safe-diagnostics

    retention-days: 7
- name: Validate safe failure diagnostics
  id: safe-diagnostics
  if: ${{ failure() }}
  run: python3 scripts/e2e_runtime_diagnostics.py .e2e-diagnostics .e2e-validated
- name: Retain validated safe failure diagnostics
  if: ${{ failure() && steps.safe-diagnostics.outcome == 'success' }}
  uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4.6.2
  with:
    name: safe-runtime-${{ matrix.name }}-${{ github.run_id }}-${{ github.run_attempt }}

replacements.new:
    retention-days: 7
- name: Validate safe failure diagnostics
  id: safe-diagnostics
  if: ${{ failure() && matrix.name != 'tasks-health-recovery' }}
  run: python3 scripts/e2e_runtime_diagnostics.py .e2e-diagnostics .e2e-validated
- name: Retain validated safe failure diagnostics
  if: ${{ failure() && matrix.name != 'tasks-health-recovery' && steps.safe-diagnostics.outcome == 'success' }}
  uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4.6.2
  with:
    name: safe-runtime-${{ matrix.name }}-${{ github.run_id }}-${{ github.run_attempt }}

browser:
  if: ${{ needs.plan.outputs.browser == 'true' }}
  needs: [plan, prepare-postgres]
  env:
    ADTR_E2E_NATIVE_STREAM_MODE: ${{ (matrix.name == 'group-asset-export-v3-running-cancel' || matrix.name == 'computer-asset-export-v3-running-cancel' || matrix.name == 'user-asset-export-v3-running-cancel' || matrix.name == 'computer-asset-export-v3' || matrix.name == 'computer-asset-export-v3-failure' || matrix.name == 'computer-asset-export-v3-cancel' || matrix.name == 'group-asset-export-v3' || matrix.name == 'group-asset-export-v3-failure' || matrix.name == 'group-asset-export-v3-cancel' || matrix.name == 'user-asset-export-v3-failure' || matrix.name == 'user-asset-export-v3-cancel' || matrix.name == 'user-asset-export-v3' || matrix.name == 'user-assets-v2' || matrix.name == 'user-assets-v2-readers' || matrix.name == 'user-assets-v3' || matrix.name == 'computer-assets-v3' || matrix.name == 'computer-assets-v3-readers' || matrix.name == 'group-assets-v3' || matrix.name == 'group-assets-v3-readers') && 'stable-body' || 'native-finish' }}
  runs-on: ubuntu-24.04
  timeout-minutes: ${{ matrix.name == 'tasks-health-recovery' && 30 || 20 }}
  permissions:
    contents: read
  strategy:
    fail-fast: false
    max-parallel: 8
    matrix: ${{ fromJSON(needs.plan.outputs.browser_matrix) }}
